"""Verify the exact Finder records generated by build_dmg without editing them."""
import pathlib
import plistlib
import re
import struct
import subprocess
import sys
import tempfile


def blob(data, filename, code):
    # Generated records use: UTF-16BE filename, four-byte key, type, payload size.
    # Reject missing or duplicate records rather than assuming a valid layout.
    prefix = struct.pack(">I", len(filename)) + filename.encode("utf-16-be") + code + b"blob"
    if data.count(prefix) != 1:
        raise ValueError("Missing or duplicate Finder layout record")
    start = data.index(prefix) + len(prefix)
    size = struct.unpack_from(">I", data, start)[0]
    if size > len(data) - start - 4:
        raise ValueError("Truncated Finder layout record")
    return data[start + 4:start + 4 + size]


def main():
    mount = pathlib.Path(sys.argv[1]).resolve()
    data = (mount / ".DS_Store").read_bytes()
    icon_view = plistlib.loads(blob(data, ".", b"icvp"))
    window = plistlib.loads(blob(data, ".", b"bwsp"))
    if (icon_view.get("backgroundType") != 2 or icon_view.get("arrangeBy") != "none"
            or icon_view.get("textSize") != 14 or not icon_view.get("labelOnBottom")
            or not 100 <= icon_view.get("iconSize", 0) <= 120):
        raise ValueError("Unexpected Finder icon-view options")
    bounds = re.findall(r"\d+", window.get("WindowBounds", ""))
    if bounds[-2:] != ["900", "600"] or window.get("ShowToolbar") or window.get("ShowStatusBar"):
        raise ValueError("Unexpected Finder window layout")
    for name, expected in (("FCP Cleaner.app", (200, 245)), ("Applications", (700, 245)),
                           ("安装说明.txt", (450, 415))):
        record = blob(data, name, b"Iloc")
        if len(record) != 16 or struct.unpack_from(">II", record) != expected:
            raise ValueError("Unexpected Finder icon position")
    alias = icon_view.get("backgroundImageAlias")
    if not isinstance(alias, bytes) or not alias:
        raise ValueError("Missing Finder background alias")
    with tempfile.TemporaryDirectory(prefix="fcp-layout-verify-", dir="/private/tmp") as directory:
        work = pathlib.Path(directory)
        record = work / "background.alias-data"
        record.write_bytes(alias)
        subprocess.run(["/usr/bin/swift", "-suppress-warnings", "-module-cache-path", str(work / "module-cache"),
                        str(pathlib.Path(__file__).with_name("resolve_finder_alias.swift")), str(record),
                        str(mount / ".background/background.png")], check=True)
    print("Finder background, window size and all three icon positions verified")


if __name__ == "__main__":
    main()
